const b = $input.first().json.body || $input.first().json;
const fields = ['LIMIT_BAL','SEX','EDUCATION','MARRIAGE','AGE','PAY_0','PAY_2','PAY_3','PAY_4','PAY_5','PAY_6','BILL_AMT1','BILL_AMT2','BILL_AMT3','BILL_AMT4','BILL_AMT5','BILL_AMT6','PAY_AMT1','PAY_AMT2','PAY_AMT3','PAY_AMT4','PAY_AMT5','PAY_AMT6'];
const out = {};
for (const f of fields) out[f] = b[f] ?? null;
const lim = Number(out.LIMIT_BAL) || 1;
out.bill_to_limit_ratio = parseFloat((Number(out.BILL_AMT1) / lim).toFixed(4));
out.payment_coverage_ratio = out.BILL_AMT1 > 0 ? parseFloat((Number(out.PAY_AMT1) / Number(out.BILL_AMT1)).toFixed(4)) : null;
out.consecutive_delays = [out.PAY_0, out.PAY_2, out.PAY_3, out.PAY_4, out.PAY_5, out.PAY_6].filter(v => Number(v) >= 1).length;
out.bill_trend = Number(out.BILL_AMT1) - Number(out.BILL_AMT6);
return [{ json: out }];

