const raw = $input.first().json.output || $input.first().json.text || $input.first().json.content || '';
let parsed;
try {
  const cleaned = raw.replace(/```json?\n?/gi,'').replace(/```/g,'').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : cleaned);
} catch(e) {
  parsed = { risk_level:'UNKNOWN', default_probability:null, rf_classification:'ERROR', key_signals:['Parse error: '+String(e.message)], manager_recommendation:'Manual review required.', risk_exposure_ntd:0 };
}
return [{ json: parsed }];

var risk = $input.first().json;
var level = risk.risk_level || 'UNKNOWN';
var prob = ((risk.default_probability || 0) * 100).toFixed(0);
var rfClass = risk.rf_classification || 'N/A';
var signals = (risk.key_signals || []).join('\n  • ');
var rec = risk.manager_recommendation || 'Manual review required.';
var exposure = risk.risk_exposure_ntd ? 'NTD ' + Number(risk.risk_exposure_ntd).toLocaleString() : 'N/A';

var emailBody = '══════════════════════════════════\n';
emailBody += '  CREDIT RISK ALERT — ' + level + ' RISK\n';
emailBody += '══════════════════════════════════\n\n';
emailBody += 'RF Model Classification : ' + rfClass + '\n';
emailBody += 'Default Probability     : ' + prob + '%\n';
emailBody += 'Risk Exposure (NTD)     : ' + exposure + '\n\n';
emailBody += 'Key Risk Signals:\n  • ' + signals + '\n\n';
emailBody += 'Manager Recommendation:\n  ' + rec + '\n\n';
emailBody += '──────────────────────────────────\n';
emailBody += 'Africa Business School — UM6P 2026\n';
emailBody += 'Credit Assessment Agent (AI + RF Model)\n';

var waMsg = encodeURIComponent(
  '🚨 CREDIT ALERT — ' + level + ' RISK\n' +
  'RF: ' + rfClass + ' | P=' + prob + '%\n' +
  'Exposure: ' + exposure + '\n' +
  rec
);

return [{ json: Object.assign({}, risk, { emailBody: emailBody, whatsappMessage: waMsg, alertLevel: level }) }];
